static unsigned vm_native_exec_section_coverage_count(void) {
    return (unsigned)(sizeof(k_vm_native_exec_section_coverage) / sizeof(k_vm_native_exec_section_coverage[0]));
}

static unsigned vm_native_recovered_range_count(void) {
    return (unsigned)(sizeof(k_vm_native_recovered_ranges) / sizeof(k_vm_native_recovered_ranges[0]));
}

static unsigned vm_native_executable_gap_count(void) {
    return (unsigned)(sizeof(k_vm_native_executable_gaps) / sizeof(k_vm_native_executable_gaps[0]));
}

